head.script:
/*
 * WAEA-966 가이드 샘플 - Pivot pivotExcelDownload Excel 인쇄용 머리글/바닥글 설정
 *
 * [옵션 규격] (GridView advancedExcelDownload의 WAEA-950 규격과 동일)
 *   options.printSet.header : 엑셀 인쇄용 머리글. { left, center, right } 객체 또는 문자열(=center) 지정
 *   options.printSet.footer : 엑셀 인쇄용 바닥글. { left, center, right } 객체 또는 문자열(=center) 지정
 *
 * [주의]
 *   - 값은 리터럴 텍스트로 처리되며, &P(페이지 번호) 등 Excel 머리글/바닥글 필드 코드는 지원하지 않는다.
 *   - & 문자는 그대로 출력된다 (엔진이 내부적으로 escape 처리).
 *   - header/footer 미지정 시 기존 다운로드 결과와 동일하다 (하위호환).
 *   - 확인 방법: 다운로드한 Excel에서 [삽입 > 머리글/바닥글] 또는 인쇄 미리보기.
 */
scwin.onpageload = function() {
    dataList1.setJSON([
        { region:"서울", industry:"제조",   amount:100 },
        { region:"서울", industry:"서비스", amount:30  },
        { region:"부산", industry:"제조",   amount:200 },
        { region:"부산", industry:"서비스", amount:70  }
    ]);
};

// 1) left/center/right 객체로 머리글/바닥글 지정
scwin.downloadObjectForm = function() {
    pivotTable1.pivotExcelDownload({
        fileName: "WAEA_966_headerFooter.xlsx",
        printSet: {
            header: { left: "농협은행", center: "월별 실적 집계", right: "대외비" },
            footer: { center: "출력용 - 재배포 금지" }
        }
    });
};

// 2) 문자열로 지정하면 중앙(center) 머리글로 처리
scwin.downloadStringForm = function() {
    pivotTable1.pivotExcelDownload({
        fileName: "WAEA_966_headerCenter.xlsx",
        printSet: {
            header: "월별 실적 집계"
        }
    });
};

// 3) 미지정 - 기존 다운로드와 동일 (하위호환 확인용)
scwin.downloadDefault = function() {
    pivotTable1.pivotExcelDownload({
        fileName: "WAEA_966_default.xlsx"
    });
};
